//! Bundled English item and style names.
//!
//! Savegames store ids, not names. When no game installation is available the
//! editor falls back to this generated index, which contains only the item and
//! style names and the item category. It is not a replacement for the game
//! data: descriptions, upgrade tables and effect names still require an
//! installation.
//!
//! The index is generated by `jadeforge-cli export-names` from an English
//! retail installation. The repository rule allows this one extracted table
//! because it is small, human readable and limited to display names.

use std::collections::BTreeMap;
use std::sync::LazyLock;

use serde::{Deserialize, Serialize};

use crate::error::{Error, Result};
use crate::gamedata::{GameData, save_type_for_category};

/// Version of the embedded TOML schema.
const FORMAT_VERSION: u32 = 1;

/// Source description written into generated indexes.
const SOURCE: &str = "Jade Empire English installation (items.2da, stylesuperlist.2da, dialog.tlk)";

/// Header prepended to generated indexes.
const HEADER: &str = "# Generated by `jadeforge-cli export-names`; do not edit by hand.\n\
                      # English item and style names and item categories only.\n";

/// The compiled-in English index.
const BUNDLED_EN: &str = include_str!("../data/names-en.toml");

/// One item of the bundled index.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BundledItem {
    /// Row in `items.2da`.
    pub id: u16,
    /// English display name from the talk table.
    pub name: String,
    /// Category as written in `items.2da`, for example `weapons`.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub category: Option<String>,
}

impl BundledItem {
    /// Value the savegame uses in the `Type` field of an item struct.
    #[must_use]
    pub fn save_type(&self) -> Option<u8> {
        self.category.as_deref().and_then(save_type_for_category)
    }
}

/// One style of the bundled index.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct BundledStyle {
    id: u16,
    name: String,
}

/// The on-disk TOML shape.
#[derive(Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
struct IndexFile {
    format: u32,
    language: String,
    source: String,
    #[serde(default)]
    items: Vec<BundledItem>,
    #[serde(default)]
    styles: Vec<BundledStyle>,
}

/// A validated, immutable name index.
#[derive(Debug)]
pub struct NameIndex {
    language: String,
    source: String,
    items: BTreeMap<u16, BundledItem>,
    styles: BTreeMap<u16, String>,
}

impl NameIndex {
    /// Returns the index compiled into the binary.
    ///
    /// `None` means the embedded table is malformed; tests catch that case, and
    /// the editor simply keeps using numeric ids.
    #[must_use]
    pub fn bundled_english() -> Option<&'static Self> {
        static INDEX: LazyLock<Option<NameIndex>> =
            LazyLock::new(|| NameIndex::parse(BUNDLED_EN).ok());
        INDEX.as_ref()
    }

    /// Parses and validates an index from TOML.
    pub fn parse(text: &str) -> Result<Self> {
        let file: IndexFile =
            toml::from_str(text).map_err(|error| Error::Names(error.to_string()))?;
        if file.format != FORMAT_VERSION {
            return Err(Error::Names(format!(
                "unsupported format {}, expected {FORMAT_VERSION}",
                file.format
            )));
        }
        let language = file.language.trim().to_owned();
        if language.is_empty() {
            return Err(Error::Names("language is empty".to_owned()));
        }
        let source = file.source.trim().to_owned();
        if source.is_empty() {
            return Err(Error::Names("source is empty".to_owned()));
        }

        let mut items = BTreeMap::new();
        for mut item in file.items {
            let trimmed_name = item.name.trim().to_owned();
            item.name = trimmed_name;
            if item.name.is_empty() || item.name == "****" {
                return Err(Error::Names(format!("item {} has an empty name", item.id)));
            }
            item.category = item.category.and_then(|category| {
                let category = category.trim().to_lowercase();
                (!category.is_empty()).then_some(category)
            });
            let id = item.id;
            if items.insert(id, item).is_some() {
                return Err(Error::Names(format!("duplicate item id {id}")));
            }
        }

        let mut styles = BTreeMap::new();
        for style in file.styles {
            let name = style.name.trim().to_owned();
            if name.is_empty() || name == "****" {
                return Err(Error::Names(format!(
                    "style {} has an empty name",
                    style.id
                )));
            }
            if styles.insert(style.id, name).is_some() {
                return Err(Error::Names(format!("duplicate style id {}", style.id)));
            }
        }

        Ok(Self {
            language,
            source,
            items,
            styles,
        })
    }

    /// Language code of the index, currently always `en`.
    #[must_use]
    pub fn language(&self) -> &str {
        &self.language
    }

    /// Human readable provenance of the index.
    #[must_use]
    pub fn source(&self) -> &str {
        &self.source
    }

    /// Looks an item up by its `items.2da` row.
    #[must_use]
    pub fn item(&self, id: u16) -> Option<&BundledItem> {
        self.items.get(&id)
    }

    /// Looks a style up by its `stylesuperlist.2da` row.
    #[must_use]
    pub fn style(&self, id: u16) -> Option<&str> {
        self.styles.get(&id).map(String::as_str)
    }

    /// All named items, ordered by id.
    pub fn items(&self) -> impl Iterator<Item = &BundledItem> {
        self.items.values()
    }

    /// All named styles, ordered by id.
    pub fn styles(&self) -> impl Iterator<Item = (u16, &str)> {
        self.styles.iter().map(|(id, name)| (*id, name.as_str()))
    }

    /// Items that carry a category and can therefore be added to a savegame.
    pub fn addable_items(&self) -> impl Iterator<Item = &BundledItem> {
        self.items().filter(|item| item.save_type().is_some())
    }

    /// Number of named items.
    #[must_use]
    pub fn item_count(&self) -> usize {
        self.items.len()
    }

    /// Number of items that can be added to a savegame.
    #[must_use]
    pub fn addable_item_count(&self) -> usize {
        self.addable_items().count()
    }

    /// Number of named styles.
    #[must_use]
    pub fn style_count(&self) -> usize {
        self.styles.len()
    }

    /// Searches addable items by name.
    ///
    /// An empty query returns the whole database, so the picker is browsable
    /// without typing. The total is returned separately from the page so the
    /// UI can show "n of m".
    #[must_use]
    pub fn search_items(&self, query: &str, limit: usize) -> (Vec<&BundledItem>, usize) {
        let query = query.trim().to_lowercase();
        if query.is_empty() {
            let mut all: Vec<&BundledItem> = self.addable_items().collect();
            all.sort_by(|left, right| {
                left.name
                    .to_lowercase()
                    .cmp(&right.name.to_lowercase())
                    .then_with(|| left.id.cmp(&right.id))
            });
            let total = all.len();
            return (all.into_iter().take(limit).collect(), total);
        }

        let mut matches: Vec<(bool, &BundledItem, String)> = Vec::new();
        for item in self.addable_items() {
            let name = item.name.to_lowercase();
            if name.contains(&query) {
                matches.push((name.starts_with(&query), item, name));
            }
        }
        matches.sort_by(|left, right| {
            right
                .0
                .cmp(&left.0)
                .then_with(|| left.2.cmp(&right.2))
                .then_with(|| left.1.id.cmp(&right.1.id))
        });
        let total = matches.len();
        (
            matches
                .into_iter()
                .take(limit)
                .map(|(_, item, _)| item)
                .collect(),
            total,
        )
    }
}

/// Builds the English name index from a loaded installation.
///
/// Only playable item names, their categories, and style names are written.
/// Descriptions and table data are deliberately left out.
pub fn export_english(game: &GameData) -> Result<String> {
    let mut items: Vec<BundledItem> = game
        .playable_items()
        .map(|item| BundledItem {
            id: item.id,
            name: item.name.clone(),
            category: item.category.clone(),
        })
        .collect();
    items.sort_by_key(|item| item.id);

    let mut styles: Vec<BundledStyle> = game
        .styles()
        .map(|style| BundledStyle {
            id: style.id,
            name: style.name.clone(),
        })
        .collect();
    styles.sort_by_key(|style| style.id);

    let file = IndexFile {
        format: FORMAT_VERSION,
        language: "en".to_owned(),
        source: SOURCE.to_owned(),
        items,
        styles,
    };
    let body = toml::to_string_pretty(&file).map_err(|error| Error::Names(error.to_string()))?;
    Ok(format!("{HEADER}{body}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = r#"
format = 1
language = "en"
source = "test"

[[items]]
id = 2
name = "Sword"
category = "weapons"

[[items]]
id = 1
name = "Gem"
category = "gems"

[[styles]]
id = 21
name = "Thousand Cuts"
"#;

    #[test]
    fn parses_and_sorts_by_id() {
        let index = NameIndex::parse(SAMPLE).expect("parse sample");
        assert_eq!(index.language(), "en");
        assert_eq!(index.source(), "test");
        assert_eq!(index.item(1).expect("gem").name, "Gem");
        assert_eq!(index.item(2).expect("sword").save_type(), Some(5));
        assert_eq!(index.style(21), Some("Thousand Cuts"));
        assert_eq!(index.item_count(), 2);
        assert_eq!(index.addable_item_count(), 2);
        assert_eq!(index.style_count(), 1);
        let ids: Vec<u16> = index.items().map(|item| item.id).collect();
        assert_eq!(ids, [1, 2]);
    }

    #[test]
    fn search_ranks_prefix_matches_first() {
        let index = NameIndex::parse(
            r#"
format = 1
language = "en"
source = "test"

[[items]]
id = 1
name = "Iron Sword"
category = "weapons"

[[items]]
id = 2
name = "Sword of Fire"
category = "weapons"

[[items]]
id = 3
name = "Gem"
category = "gems"
"#,
        )
        .expect("parse sample");
        let (matches, total) = index.search_items("sword", 10);
        assert_eq!(total, 2);
        assert_eq!(matches[0].name, "Sword of Fire");
        assert_eq!(matches[1].name, "Iron Sword");
        let (all, total) = index.search_items("", 1);
        assert_eq!(total, 3);
        assert_eq!(all.len(), 1);
    }

    #[test]
    fn rejects_extra_fields_and_bad_formats() {
        let with_description = SAMPLE.replace(
            "name = \"Thousand Cuts\"",
            "name = \"Thousand Cuts\"\ndescription = \"leak\"",
        );
        assert!(NameIndex::parse(&with_description).is_err());
        let bad_format = SAMPLE.replace("format = 1", "format = 2");
        assert!(NameIndex::parse(&bad_format).is_err());
    }

    #[test]
    fn unknown_categories_are_kept_but_not_addable() {
        let text = SAMPLE.replace("category = \"weapons\"", "category = \"nonsense\"");
        let index = NameIndex::parse(&text).expect("parse custom category");
        let item = index.item(2).expect("custom category item");
        assert_eq!(item.category.as_deref(), Some("nonsense"));
        assert_eq!(item.save_type(), None);
        assert_eq!(index.addable_item_count(), 1);
    }

    #[test]
    fn embedded_index_is_well_formed() {
        let index = NameIndex::bundled_english().expect("embedded name index");
        assert_eq!(index.language(), "en");
        assert!(index.item_count() > 100);
        assert!(index.addable_item_count() > 100);
        assert!(index.style_count() > 20);
        assert!(index.items().all(|item| !item.name.is_empty()));
        assert!(index.styles().all(|(_, name)| !name.is_empty()));
        assert_eq!(index.style(21), Some("Thousand Cuts"));
        assert_eq!(
            index.item(369).map(|item| item.name.as_str()),
            Some("Flawless")
        );
    }
}
